// Inspect Button and Text Field components to understand default styling
const button = figma.getNodeById('1:23');
const textField = figma.getNodeById('1:26');

function inspect(node, depth = 0) {
  if (!node || depth > 5) return null;
  const info = {
    name: node.name,
    type: node.type,
    width: Math.round(node.width || 0),
    height: Math.round(node.height || 0),
  };
  if (node.type === 'TEXT') {
    info.characters = node.characters;
    info.fontSize = node.fontSize;
    info.fontName = node.fontName;
  }
  if (node.type === 'FRAME' || node.type === 'COMPONENT' || node.type === 'INSTANCE' || node.type === 'RECTANGLE') {
    info.fills = node.fills && node.fills.length ? node.fills.map(f => ({ type: f.type, color: f.color, visible: f.visible })) : null;
    info.cornerRadius = node.cornerRadius;
    info.layoutMode = node.layoutMode;
    info.padding = node.paddingLeft !== undefined ? [node.paddingTop, node.paddingRight, node.paddingBottom, node.paddingLeft] : null;
    info.itemSpacing = node.itemSpacing;
  }
  if (node.children && node.children.length) {
    info.children = node.children.map(c => inspect(c, depth + 1));
  }
  return info;
}

return { button: inspect(button), textField: inspect(textField) };

// Get image hashes from media symbols so we can reuse them as fills
const ids = ['4:36','4:44','4:45','4:46','4:47','4:32','4:33','4:49','4:34','4:35','4:37','4:40','4:41','4:42','4:43','4:48','4:51','4:38','4:39','4:50'];
const result = {};
for (const id of ids) {
  const node = figma.getNodeById(id);
  if (node) {
    // Find image fills inside
    function findImageFill(n) {
      if (n.fills) {
        const img = (n.fills || []).find(f => f.type === 'IMAGE');
        if (img) return img.imageHash;
      }
      if (n.children) {
        for (const c of n.children) {
          const h = findImageFill(c);
          if (h) return h;
        }
      }
      return null;
    }
    result[node.name] = { id: node.id, hash: findImageFill(node) };
  }
}
return result;

