// Helpers
const H = {
  solid(hex) {
    const c = hex.replace('#','');
    const r = parseInt(c.substring(0,2),16)/255, g = parseInt(c.substring(2,4),16)/255, b = parseInt(c.substring(4,6),16)/255;
    return [{ type:'SOLID', color:{r,g,b} }];
  },
  rgba(hex, a) {
    const c = hex.replace('#','');
    const r = parseInt(c.substring(0,2),16)/255, g = parseInt(c.substring(2,4),16)/255, b = parseInt(c.substring(4,6),16)/255;
    return [{ type:'SOLID', color:{r,g,b}, opacity:a }];
  },
  img(hash, scaleMode='FILL') {
    return [{ type:'IMAGE', imageHash:hash, scaleMode }];
  },
  text(chars, fontSize, style='Regular', colorHex='#000000', family='Plus Jakarta Sans', opacity=1) {
    const t = figma.createText();
    t.fontName = { family, style };
    t.fontSize = fontSize;
    t.characters = chars;
    t.fills = H.solid(colorHex);
    if (opacity < 1) t.opacity = opacity;
    return t;
  },
  frame(name, w, h, fillHex=null) {
    const f = figma.createFrame();
    f.name = name;
    f.resize(w, h);
    f.fills = fillHex ? H.solid(fillHex) : [];
    return f;
  }
};
