// Helper: build product card instance with custom data
function productCard(name, hash, rating, price, oldPrice, discount) {
  const inst = cardComp.createInstance();
  inst.name = 'Product / ' + name;
  const img = inst.findOne(n => n.name === 'Image');
  img.fills = [{ type:'IMAGE', imageHash: hash, scaleMode:'FILL' }];
  const nameT = inst.findOne(n => n.name === 'Name');
  nameT.characters = name;

  // rebuild rating
  const ratingWrap = inst.findOne(n => n.name === 'Rating');
  const starsWrap = ratingWrap.findOne(n => n.name === 'Stars');
  // clear existing stars
  for (const c of [...starsWrap.children]) c.remove();
  const full = Math.floor(rating);
  const hasHalf = rating % 1 >= 0.5;
  for (let i = 0; i < full; i++) {
    const s = starIcon.createInstance();
    s.fills = H.solid('#FFC633');
    s.resize(18.5, 18.5);
    starsWrap.appendChild(s);
  }
  if (hasHalf) {
    const s = starHalfIcon.createInstance();
    s.fills = H.solid('#FFC633');
    s.resize(9, 18.5);
    starsWrap.appendChild(s);
  }
  const scoreT = ratingWrap.findOne(n => n.name === 'Score');
  scoreT.characters = rating.toFixed(1) + '/5';

  const priceRow = inst.findOne(n => n.name === 'Price');
  // clear children and rebuild
  for (const c of [...priceRow.children]) c.remove();
  const p = H.text('$' + price, 24, 'Bold', '#000000');
  priceRow.appendChild(p);
  if (oldPrice) {
    const o = H.text('$' + oldPrice, 24, 'Bold', '#000000', 'Plus Jakarta Sans', 0.4);
    o.textDecoration = 'STRIKETHROUGH';
    priceRow.appendChild(o);
    const disc = figma.createFrame();
    disc.name = 'Discount';
    disc.paddingLeft = 14; disc.paddingRight = 14; disc.paddingTop = 6; disc.paddingBottom = 6;
    disc.cornerRadius = 62;
    disc.fills = H.rgba('#FF3333', 0.1);
    disc.counterAxisSizingMode = 'AUTO';
    disc.primaryAxisSizingMode = 'AUTO';
    disc.layoutMode = 'HORIZONTAL';
    const dTxt = H.text('-' + discount + '%', 12, 'Medium', '#FF3333');
    disc.appendChild(dTxt);
    priceRow.appendChild(disc);
  }
  return inst;
}

