function pageBtn(label, opts = {}) {
  const b = figma.createFrame();
  b.name = 'Page / ' + label;
  b.layoutMode = 'HORIZONTAL';
  b.paddingLeft = 14; b.paddingRight = 14; b.paddingTop = 8; b.paddingBottom = 8;
  b.counterAxisSizingMode = 'AUTO';
  b.primaryAxisSizingMode = 'AUTO';
  b.counterAxisAlignItems = 'CENTER';
  b.primaryAxisAlignItems = 'CENTER';
  b.cornerRadius = 8;
  b.itemSpacing = 8;
  if (opts.active) {
    b.fills = H.rgba('#000000', 0.06);
  } else if (opts.bordered) {
    b.fills = H.solid('#FFFFFF');
    b.strokes = H.rgba('#000000', 0.1);
    b.strokeWeight = 1;
  } else {
    b.fills = [];
  }
  const t = H.text(label, 14, opts.active ? 'Medium' : 'Regular', '#000000', 'Plus Jakarta Sans', opts.disabled ? 0.4 : 1);
  b.appendChild(t);
  return b;
}
function arrowBtn(dir) {
  const b = figma.createFrame();
  b.name = 'Page / ' + dir;
  b.layoutMode = 'HORIZONTAL';
  b.paddingLeft = 14; b.paddingRight = 14; b.paddingTop = 8; b.paddingBottom = 8;
  b.counterAxisSizingMode = 'AUTO';
  b.primaryAxisSizingMode = 'AUTO';
  b.counterAxisAlignItems = 'CENTER';
  b.cornerRadius = 8;
  b.itemSpacing = 8;
  b.fills = H.solid('#FFFFFF');
  b.strokes = H.rgba('#000000', 0.1);
  b.strokeWeight = 1;
  if (dir === 'Previous') {
    const ic = figma.getNodeById('4:4').createInstance();
    ic.resize(16, 16);
    b.appendChild(ic);
  }
  const t = H.text(dir, 14, 'Medium', '#000000');
  b.appendChild(t);
  if (dir === 'Next') {
    const ic = figma.getNodeById('4:6').createInstance();
    ic.resize(16, 16);
    b.appendChild(ic);
  }
  return b;
}

