function dump(n, depth=0) {
  if (depth > 4) return null;
  const o = {
    name: n.name, type: n.type,
    w: Math.round(n.width||0), h: Math.round(n.height||0),
    layoutMode: n.layoutMode,
    primaryAxisSizingMode: n.primaryAxisSizingMode,
    counterAxisSizingMode: n.counterAxisSizingMode,
    layoutAlign: n.layoutAlign,
    layoutGrow: n.layoutGrow,
  };
  if (n.children) o.children = n.children.map(c => dump(c, depth+1));
  return o;
}
return dump(category);

