function reviewCard(r) {
  const card = figma.createFrame();
  card.name = 'Review / ' + r.name;
  card.layoutMode = 'VERTICAL';
  card.paddingLeft = 32; card.paddingRight = 32; card.paddingTop = 28; card.paddingBottom = 28;
  card.itemSpacing = 12;
  card.cornerRadius = 20;
  card.fills = H.solid('#FFFFFF');
  card.strokes = H.rgba('#000000', 0.1);
  card.strokeWeight = 1;
  card.counterAxisSizingMode = 'FIXED';
  card.primaryAxisSizingMode = 'AUTO';
  card.resize(610, 100);

  const top = figma.createFrame();
  top.fills = [];
  top.layoutMode = 'HORIZONTAL';
  top.primaryAxisSizingMode = 'FIXED';
  top.counterAxisSizingMode = 'AUTO';
  top.primaryAxisAlignItems = 'SPACE_BETWEEN';
  top.counterAxisAlignItems = 'CENTER';
  top.layoutAlign = 'STRETCH';

  const stars = figma.createFrame();
  stars.fills = [];
  stars.layoutMode = 'HORIZONTAL';
  stars.itemSpacing = 5;
  stars.counterAxisSizingMode = 'AUTO';
  stars.primaryAxisSizingMode = 'AUTO';
  const full = Math.floor(r.rating);
  const hasHalf = (r.rating % 1) >= 0.25;
  for (let i = 0; i < full; i++) {
    const s = starIcon.createInstance();
    s.fills = H.solid('#FFC633');
    s.resize(22.6, 22.6);
    stars.appendChild(s);
  }
  if (hasHalf) {
    const s = starHalfIcon.createInstance();
    s.fills = H.solid('#FFC633');
    s.resize(11.3, 22.6);
    stars.appendChild(s);
  }
  top.appendChild(stars);
  const more = moreIcon.createInstance();
  more.resize(24, 24);
  top.appendChild(more);
  card.appendChild(top);

  const nameRow = figma.createFrame();
  nameRow.fills = [];
  nameRow.layoutMode = 'HORIZONTAL';
  nameRow.itemSpacing = 8;
  nameRow.counterAxisAlignItems = 'CENTER';
  nameRow.counterAxisSizingMode = 'AUTO';
  nameRow.primaryAxisSizingMode = 'AUTO';
  nameRow.appendChild(H.text(r.name, 20, 'Bold', '#000000'));
  const vi = verifiedIcon.createInstance();
  vi.resize(24, 24);
  nameRow.appendChild(vi);
  card.appendChild(nameRow);

  const quote = H.text('"' + r.text + '"', 16, 'Regular', '#000000', 'Plus Jakarta Sans', 0.6);
  quote.layoutAlign = 'STRETCH';
  quote.textAutoResize = 'HEIGHT';
  quote.lineHeight = { value: 22, unit: 'PIXELS' };
  card.appendChild(quote);

  card.appendChild(H.text(r.date, 16, 'Medium', '#000000', 'Plus Jakarta Sans', 0.6));
  return card;
}

