// Helper: product card
function buildCard(name, hash, rating, price, oldPrice, discount) {
  const card = figma.createFrame();
  card.name = 'Product / ' + name;
  card.layoutMode = 'VERTICAL';
  card.itemSpacing = 12;
  card.counterAxisSizingMode = 'AUTO';
  card.primaryAxisSizingMode = 'AUTO';
  card.fills = [];

  const thumb = figma.createFrame();
  thumb.name = 'Image';
  thumb.resize(295, 298);
  thumb.cornerRadius = 20;
  thumb.fills = [{ type:'IMAGE', imageHash: hash, scaleMode:'FILL' }];
  card.appendChild(thumb);

  const info = figma.createFrame();
  info.name = 'Info';
  info.fills = [];
  info.layoutMode = 'VERTICAL';
  info.itemSpacing = 8;
  info.counterAxisSizingMode = 'AUTO';
  info.primaryAxisSizingMode = 'AUTO';

  const nameT = H.text(name, 20, 'Bold', '#000000');
  nameT.name = 'Name';
  nameT.textAutoResize = 'HEIGHT';
  nameT.resize(295, 0);
  info.appendChild(nameT);

  const ratingWrap = figma.createFrame();
  ratingWrap.fills = [];
  ratingWrap.layoutMode = 'HORIZONTAL';
  ratingWrap.itemSpacing = 8;
  ratingWrap.counterAxisAlignItems = 'CENTER';
  ratingWrap.counterAxisSizingMode = 'AUTO';
  ratingWrap.primaryAxisSizingMode = 'AUTO';
  const starsWrap = figma.createFrame();
  starsWrap.fills = [];
  starsWrap.layoutMode = 'HORIZONTAL';
  starsWrap.itemSpacing = 5;
  starsWrap.counterAxisSizingMode = 'AUTO';
  starsWrap.primaryAxisSizingMode = 'AUTO';
  const full = Math.floor(rating);
  const hasHalf = (rating % 1) >= 0.25;
  for (let i = 0; i < full; i++) {
    const s = starIcon.createInstance();
    s.fills = H.solid('#FFC633');
    s.resize(18.5, 18.5);
    starsWrap.appendChild(s);
  }
  if (hasHalf) {
    const s = starHalfIcon.createInstance();
    s.fills = H.solid('#FFC633');
    s.resize(9, 18.5);
    starsWrap.appendChild(s);
  }
  ratingWrap.appendChild(starsWrap);
  ratingWrap.appendChild(H.text(rating.toFixed(1) + '/5', 14, 'Regular', '#000000'));
  info.appendChild(ratingWrap);

  const priceRow = figma.createFrame();
  priceRow.fills = [];
  priceRow.layoutMode = 'HORIZONTAL';
  priceRow.itemSpacing = 10;
  priceRow.counterAxisAlignItems = 'CENTER';
  priceRow.counterAxisSizingMode = 'AUTO';
  priceRow.primaryAxisSizingMode = 'AUTO';
  priceRow.appendChild(H.text('$' + price, 24, 'Bold', '#000000'));
  if (oldPrice) {
    const o = H.text('$' + oldPrice, 24, 'Bold', '#000000', 'Plus Jakarta Sans', 0.4);
    o.textDecoration = 'STRIKETHROUGH';
    priceRow.appendChild(o);
    const disc = figma.createFrame();
    disc.paddingLeft = 14; disc.paddingRight = 14; disc.paddingTop = 6; disc.paddingBottom = 6;
    disc.cornerRadius = 62;
    disc.fills = H.rgba('#FF3333', 0.1);
    disc.counterAxisSizingMode = 'AUTO';
    disc.primaryAxisSizingMode = 'AUTO';
    disc.layoutMode = 'HORIZONTAL';
    disc.counterAxisAlignItems = 'CENTER';
    disc.primaryAxisAlignItems = 'CENTER';
    disc.appendChild(H.text('-' + discount + '%', 12, 'Medium', '#FF3333'));
    priceRow.appendChild(disc);
  }
  info.appendChild(priceRow);
  card.appendChild(info);
  return card;
}

