// Set up reactions using setReactionsAsync
async function link(node, targetId, nav='NAVIGATE') {
  if (!node) return;
  await node.setReactionsAsync([{
    trigger: { type: 'ON_CLICK' },
    actions: [{
      type: 'NODE',
      navigation: nav,
      destinationId: targetId,
      transition: null,
      preserveScrollPosition: false,
    }]
  }]);
}

await link(shopNow, category.id);
for (const va of viewAlls) await link(va, category.id);
await link(casualTile, category.id);
for (const c of homeCards) await link(c, product.id);
for (const ci of cartIcons) await link(ci.icon, cart.id);

return { linked: true, homeCards: homeCards.length, cartIcons: cartIcons.length };

