async function link(node, targetId) {
  if (!node) return { skipped: true };
  try {
    await node.setReactionsAsync([{
      trigger: { type: 'ON_CLICK' },
      actions: [{
        type: 'NODE',
        navigation: 'NAVIGATE',
        destinationId: targetId,
        transition: null,
        preserveScrollPosition: false,
      }]
    }]);
    return { ok: true };
  } catch (e) {
    return { error: e.message };
  }
}

