out.addBtn = await link(addBtn, cart.id);

// 03_Product breadcrumb "Shop" → 02_Category
const prodBc = product.findOne(n => n.name === 'Breadcrumb');
const shopTxt = prodBc?.findOne(n => n.type === 'TEXT' && n.characters === 'Shop');
out.shopBc = await link(shopTxt, category.id);

// 03_Product "You might also like" cards → 03_Product (self)
const ymal = product.findOne(n => n.name === 'You Might Also Like');
const ymalCards = ymal.findAll(n => n.name && n.name.startsWith('Product /'));
out.ymalCards = [];
for (const c of ymalCards) out.ymalCards.push(await link(c, product.id));

// 04_Cart breadcrumb "Home" → 01_Home
const cartHome = cart.findOne(n => n.name === 'Breadcrumb')?.findOne(n => n.type === 'TEXT' && n.characters === 'Home');
out.cartHome = await link(cartHome, home.id);

// 04_Cart items → 03_Product
const cartItems = cart.findAll(n => n.name && n.name.startsWith('Cart /'));
out.cartItems = [];
for (const c of cartItems) out.cartItems.push(await link(c, product.id));

return out;

// Final verify screenshots of all 4 frames
const page = await figma.getNodeByIdAsync('6:2');
return page.children.map(c => ({ id: c.id, name: c.name, w: Math.round(c.width), h: Math.round(c.height), x: c.x, y: c.y }));
